    for _ in range(m):
        clause = [random.choice([-1, 1]) * (i + 1) for i in random.sample(range(n), random.randint(1, n))]
        clauses.append(clause)
    return clauses

def symplectic_quotient_order(clauses):
    n = len(clauses[0])
    vectors = []
    for clause in clauses:
        vector = [0] * (2 * n)
        for literal in clause:
            var = abs(literal) - 1
            if literal > 0:
                vector[var] += 1
            else:
                vector[n + var] += 1
        vectors.append(vector)
    order = 0
    for i in range(n):
        for j in range(i + 1, n):
            if all(vectors[i][k] == vectors[j][k] for k in range(2 * n)):
                order += 1
    return order

def resolution_proof_width(clauses):
    stack = clauses[:]
    while True:
        new_clause = None
        for i in range(len(stack)):
            for j in range(i + 1, len(stack)):
                c1 = stack[i]
                c2 = stack[j]
                for literal in c1:
                    if -literal in c2:
                        new_clause = [l for l in c1 if l != literal] + [l for l in c2 if l != -literal]
                        break
                if new_clause:
                    break
            if new_clause:
